#define color32 shared_color32
#include "KS/SRC/ks/TutorialFrontEnd_shared.h"
#undef color32

class color32 {
public:
    unsigned int value;
    color32(unsigned char r, unsigned char g, unsigned char b, unsigned char a)
        : value(r | (g << 8) | (b << 16) | (a << 24)) {}
};

void *operator new(unsigned int, const char *, int);
#define NEW new(__FILE__, __LINE__)

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER };
    enum VERTJUST { VERTJUST_CENTER = 1 };
};

class BoxText {
public:
    BoxText(Font *, stringx, float, float, int, float, Font::HORIZJUST,
            Font::VERTJUST, color32, int);
    void makeBox(int, int);
};

class TextString {
public:
    TextString(Font *, stringx, float, float, int, float, Font::HORIZJUST,
               Font::VERTJUST);
    void setButtonScale(float);
    float GetScale();
};

class FEManager {
public:
    char padding[0xe694];
    Font font_info;
    Font font_bold;
};

class TutorialManager {
public:
    char padding[0x68];
    stringx button_text;
};

class ConstructorIGOFrontEnd {
public:
    char padding[0x480];
    TutorialManager *tutorial_manager;
    TutorialManager *GetTutorialManager()
    {
        return tutorial_manager;
    }
};

struct ConstructorFEManager {
    ConstructorIGOFrontEnd *IGO;
};

extern ConstructorFEManager frontendmanager;

class TutorialFrontEndConstructor : public FEMultiMenu {
    PanelQuad *bgPQs[9];
    BoxText *help_text;
    TextString *pause_button_text;
    WaveIndicatorWidget *waveIndicator;
    bool ignore_next_release;

public:
    TutorialFrontEndConstructor(FEMenuSystem *, FEManager *)
        __asm__("__16TutorialFrontEndP12FEMenuSystemP9FEManager");
};

TutorialFrontEndConstructor::TutorialFrontEndConstructor(FEMenuSystem* s, FEManager* man)
{
    cons(s, man, "", "");

    for (int i = 0; i < 9; i++)
        bgPQs[i] = NULL;

    help_text = NEW BoxText(&man->font_info, "", 135, 140, 800, 1.0f, Font::HORIZJUST_LEFT, Font::VERTJUST_CENTER, color32(255, 255, 125, 255), 15);
    help_text->makeBox(390,400);

    stringx raw_text = frontendmanager.IGO->GetTutorialManager()
        ? frontendmanager.IGO->GetTutorialManager()->button_text : "";
    pause_button_text = NEW TextString(&system->manager->font_bold, raw_text, 320, 365, 20, 0.6f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER);
    pause_button_text->setButtonScale(pause_button_text->GetScale()*1.4f);
}
